mapper.select:
select
notice.*,
types.type_name
from notice notice
left join types types on notice.type_id = types.id

    and notice.id = #{id}
    and notice.banner_img = #{bannerImg}
    and notice.type_id = #{typeId}
    and notice.content = #{content}
    and notice.info = #{info}
    and notice.create_time = #{createTime}
    and notice.title like concat('%',#{title},'%')
    and notice.see_num = #{seeNum}
    and types.type_name like concat('%',#{typeName},'%')


    limit #{current},#{pageSize}

select count(*) from notice notice
left join types types on notice.type_id = types.id

    and notice.id = #{id}
    and notice.banner_img = #{bannerImg}
    and notice.type_id = #{typeId}
    and notice.content = #{content}
    and notice.info = #{info}
    and notice.create_time = #{createTime}
    and notice.title like concat('%',#{title},'%')
    and notice.see_num = #{seeNum}
    and types.type_name like concat('%',#{typeName},'%')
